import React,{useEffect,useMemo,useState} from 'react';
import {createRoot} from 'react-dom/client';
import {Activity,ArrowDown,ArrowDownLeft,ArrowRight,ArrowUpRight,BarChart3,Bell,BookOpen,Building2,CalendarDays,Check,CheckCheck,CheckCircle2,ChevronDown,ChevronLeft,ChevronRight,ChevronsUpDown,Clock3,Columns3,Command,ContactRound,CreditCard,Download,Ellipsis,ExternalLink,Filter,Flag,HelpCircle,Inbox,LayoutDashboard,Link2,ListFilter,LogOut,Mail,Menu,MessageCircle,MoreHorizontal,PanelLeftClose,Plus,Search,Send,Settings2,ShieldCheck,SlidersHorizontal,Sparkles,Star,Target,Trash2,Users,Workflow,X,TriangleAlert,RefreshCw,Eye,LockKeyhole,GripVertical,SquareArrowOutUpRight} from 'lucide-react';
import {Data,Lead,Deal,Role,money,setDisplayCurrency,initials,relative,isRecovery,recoveryReason} from './data';
import {api,errorText,setWorkspaceId,onSessionExpired} from './api';
import {AuthScreen} from './auth';
