 {page==='Companies'&&<><div className="records-controls"><label className="search-field"><Search size={15}/><input placeholder="Search companies…" value={search} onChange={e=>setSearch(e.target.value)}/></label><span>{new Set(scopedLeads.map(l=>l.company)).size} companies</span></div><div className="company-grid">{Array.from(new Set(scopedLeads.map(l=>l.company))).filter(c=>c.toLowerCase().includes(search.toLowerCase())).map((company,i)=>{const leads=scopedLeads.filter(l=>l.company===company),deals=scopedDeals.filter(d=>d.company===company);return <button className="panel company-card" key={company} onClick={()=>setDetail(leads[0].id)}><span className={`company-logo logo-${i%5}`}>{company[0]}</span><h2>{company}</h2><p>Customer organization</p><div><span><ContactRound size={14}/>{leads.length} contact</span><span><Columns3 size={14}/>{deals.length} opportunity</span></div><footer>{canValue?money(deals.reduce((s,d)=>s+d.value,0)):'Value protected'}<ArrowUpRight size={16}/></footer></button>})}</div></>}
