 {page==='Calendar'&&<>{(()=>{const mine=(meta.calendar||[]).find((c:any)=>c.memberId===me);const ok=mine?.status==='connected';return <div className="notice"><CalendarDays size={21}/><div><strong>{ok?'Your calendar is connected.':mine?'Your calendar needs to be reconnected.':'Your time, connected.'}</strong><p>{ok?'Relay checks your busy times before booking and adds events to your Google Calendar.':'Connect your Google Calendar to check availability and book real appointments.'}</p></div>{ok?<><button className="btn" onClick={()=>open('appointment')}><Plus size={14}/>Book appointment</button><button className="btn" onClick={()=>run(()=>api('DELETE','/calendar/connection'),'Calendar disconnected.')}>Disconnect</button></>:<button className="btn" onClick={async()=>{try{const r=await api('GET','/oauth/google/start');location.href=r.url}catch(e){notify(errorText(e),true)}}}>Connect calendar<ArrowUpRight size={14}/></button>}</div>})()}{perms.has('integration.manage')&&data.team.length>0&&<div className="subtle-note"><ShieldCheck size={14}/>Calendar status: {data.team.map(t=>`${t.name} — ${((meta.calendar||[]).find((c:any)=>c.memberId===t.id)?.status||'not connected').replace('_',' ')}`).join(' · ')}</div>}<div className="calendar-layout"><section className="panel"><div className="panel-heading"><h2>Upcoming appointments</h2><Badge tone="blue">Calendar</Badge></div>{data.meetings.filter(m=>m.status!=='Cancelled').length===0&&<Empty title="No appointments yet" text="Book a meeting from a customer record or the button above."/>}{data.meetings.filter(m=>m.status!=='Cancelled').map(m=><div className="meeting-row" key={m.id}><button className="date-tile" onClick={()=>setDetail(m.contactId)} aria-label={`Open ${m.title}`}><span>{new Date(m.at).toLocaleDateString('en-US',{month:'short'})}</span><strong>{new Date(m.at).getDate()}</strong></button><div><h3>{m.title}</h3><p>{time(m.at)} · {m.duration} minutes · {Intl.DateTimeFormat().resolvedOptions().timeZone}{(m as any).timezone&&(m as any).timezone!==Intl.DateTimeFormat().resolvedOptions().timeZone?` (booked in ${(m as any).timezone})`:''}</p><span className="owner-cell"><Avatar name={p(m.owner).name} small/>{p(m.owner).name}</span></div><div style={{display:'flex',gap:6}}><button className="btn" onClick={()=>open('reschedule',m.id)}>Reschedule</button><button className="btn" onClick={()=>run(()=>api('DELETE',`/appointments/${m.id}`),'Appointment cancelled.')}>Cancel</button></div></div>)}</section><section className="panel calendar-help"><div className="round-icon"><CalendarDays size={28}/></div><h2>A little less back-and-forth.</h2><p>Bring customer meetings into the same place as their conversations, opportunities, and next steps.</p><ul><li><Check size={15}/>Busy times are checked before booking</li><li><Check size={15}/>Times are stored as exact instants with their time zone</li><li><Check size={15}/>Appointments are linked to customer records</li></ul></section></div></>}
 {page==='Team'&&<><div className="team-summary"><span><i className="online-dot"/>{data.team.filter(t=>t.status==='Available').length} available</span><span>{data.team.length} members</span><button className="btn" onClick={()=>open('invite')}><Plus size={14}/>Invite teammate</button></div><section className="panel"><div className="table-wrap"><table><thead><tr><th>Team member</th><th>Role</th><th>Availability</th><th>Open leads</th><th>Capacity</th></tr></thead><tbody>{data.team.map(t=>{const count=data.leads.filter(l=>l.owner===t.id&&l.status!=='Closed').length;return <tr key={t.id}><td><span className="person-cell"><Avatar name={t.name} color={t.color}/><span><strong>{t.name}</strong><small>{t.email}</small></span></span></td><td><Badge tone={t.role==='Owner'?'purple':'neutral'}>{t.role}</Badge></td><td><select aria-label={`${t.name} availability`} value={t.status} disabled={!canAssign&&t.id!==me} onChange={e=>{const status=e.target.value;run(()=>api('PATCH',`/team/${t.id}/availability`,{status}),status==='On leave'||status==='Offline'?'Availability updated. Unacknowledged leads were reassigned.':'Availability updated.')}}>{['Available','Busy','On leave','Offline'].map(s=><option key={s}>{s}</option>)}</select></td><td><span className="capacity"><span><i style={{width:count/t.capacity*100+'%'}}/></span>{count}/{t.capacity}</span></td><td><span className="muted">{t.capacity-count} remaining</span></td></tr>})}</tbody></table></div></section><div className="subtle-note"><ShieldCheck size={14}/>Manager is a configurable role. Owner, Admin, and User are the base access levels.</div></>}
